const qualityProfiles=[{name:'экономное',dpr:.85,shadow:0,lod:32,traffic:4,rain:300,post:false,reflect:false},{name:'сбалансированное',dpr:1,shadow:1024,lod:58,traffic:6,rain:700,post:false,reflect:false},{name:'высокое',dpr:1.35,shadow:1536,lod:85,traffic:8,rain:1200,post:true,reflect:true}];let qualityIndex=innerWidth<700||(navigator.deviceMemory&&navigator.deviceMemory<=4)?0:1,activeDPR=1,perfFrames=0,perfSeconds=0,measuredFPS=0,optFrame=0;function changeDPR(value){activeDPR=value;renderer.setPixelRatio(value);if(composer)composer.setPixelRatio(value)}function applyQuality(){const profile=qualityProfiles[qualityIndex];changeDPR(Math.min(devicePixelRatio,profile.dpr));shadowsOn=profile.shadow>0;renderer.shadowMap.enabled=shadowsOn;if(profile.shadow&&ml.shadow.mapSize.x!==profile.shadow){if(ml.shadow.map){ml.shadow.map.dispose();ml.shadow.map=null}ml.shadow.mapSize.set(profile.shadow,profile.shadow);renderer.shadowMap.needsUpdate=true}postOn=profile.post;bloomOn=profile.post;dofOn=false;rain.geometry.setDrawRange(0,profile.rain);traffic.forEach((car,i)=>car.visible=i<profile.traffic);if(reflector){reflector.visible=profile.reflect;asphalt.transparent=profile.reflect;asphalt.opacity=profile.reflect?.88:1;asphalt.depthWrite=!profile.reflect;asphalt.needsUpdate=true}contacts.forEach(o=>o.visible=true);$('quality').textContent='Качество: '+profile.name;$('shadows').textContent='Тени: '+(shadowsOn?'вкл':'выкл');$('post').textContent='Эффекты: '+(postOn?'вкл':'выкл');$('bloom').textContent='Свечение: '+(bloomOn?'вкл':'выкл');$('dof').textContent='Фокус: выкл';$('reflect').textContent='Отражения: '+(reflector&&reflector.visible?'вкл':'выкл')}$('quality').onclick=()=>{qualityIndex=(qualityIndex+1)%3;applyQuality()};$('headquartersView').onclick=()=>inspect([-29,20,-15],[0,24,-48],'Штаб-квартира Cloudplus · концептуальная архитектура','headquarters');applyQuality();
